type CardProps = {
  children: React.ReactNode;
  onActivate: () => void;
};

export function Card({ children, onActivate }: CardProps) {
  return (
    <article className="@container w-full max-w-5xl border border-ink/20 bg-surface p-6 text-ink shadow-sm">
      <div className="grid grid-cols-1 gap-6 @lg:grid-cols-3">
        <div className="min-w-0 text-base @lg:col-span-2 @lg:text-lg">
          {children}
        </div>

        <aside className="text-sm text-ink/60">sidebar</aside>
      </div>

      <button
        type="button"
        onClick={onActivate}
        className="mt-6 rounded bg-brand px-4 py-2 text-surface focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand"
      >
        Open card
      </button>
